#include <iostream>
#include <vector>
#include <iomanip>
#include <algorithm>
using namespace std;

using i64 = long long;
using i32 = int;

struct ModInt {
    i32 val;
    ModInt(i64 v = 0) : val((v % P + P) % P) {}
    ModInt& operator+=(const ModInt& o) { val = (val + o.val >= P ? val + o.val - P : val + o.val); return *this; }
    ModInt& operator*=(const ModInt& o) { val = (i64)val * o.val % P; return *this; }
    friend ModInt operator+(ModInt a, const ModInt& b) { return a += b; }
    friend ModInt operator*(ModInt a, const ModInt& b) { return a *= b; }
};

int n, m, P;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> P;

    vector<vector<ModInt>> binom(n + 2, vector<ModInt>(n + 2));
    FOR(i, 0, n + 1) {
        binom[i][0] = ModInt(1);
        FOR(j, 1, i) {
            binom[i][j] = binom[i-1][j-1] + binom[i-1][j];
        }
    }

    vector<ModInt> cnt(m + 1);
    vector<ModInt> dp1(m + 1);
    cnt[0] = ModInt(1);

    FOR(i, 1, m) {
        FOR(j, 0, i - 1) {
            ModInt term = dp1[j] * cnt[i - j - 1];
            term += dp1[i - j - 1] * cnt[j];
            term *= ModInt(j + 1);
            term += cnt[i - j - 1] * cnt[j] * ModInt(j * (j + 1) / 2);
            term *= binom[i - 1][j];
            dp1[i] += term;

            ModInt cnt_term = binom[i - 1][j] * cnt[j] * cnt[i - j - 1] * ModInt(j + 1);
            cnt[i] += cnt_term;
        }
        cnt[i] += cnt[i];
        dp1[i] += dp1[i];
    }

    vector<vector<ModInt>> dp2(n + 2, vector<ModInt>(m + 1));
    vector<vector<ModInt>> dp3(n + 2, vector<ModInt>(m + 1));
    dp2[0][0] = ModInt(1);
    dp3[0][0] = ModInt(0);

    FOR(i, 0, n) {
        FOR(j, 0, m) {
            FOR(k, 0, m) {
                if (j + k > m || i + k + 1 > n + 1) continue;
                ModInt val2 = dp2[i][j] * binom[m - j][k] * cnt[k];
                ModInt val3 = dp3[i][j] * cnt[k] + dp1[k] * dp2[i][j];
                val3 *= binom[m - j][k];
                dp2[i + k + 1][j + k] += val2;
                dp3[i + k + 1][j + k] += val3;
            }
        }
    }

    cout << dp3[n + 1][m].val << "\n";
    return 0;
}
